 1	/* ============================================================
 2	   utils.js — Shared utility functions
 3	   Section 4 of the MCP Server Dashboard SPA
 4	   ============================================================ */
 5	
 6	/**
 7	 * Build the namespaced cache key used by ProjectNameCache.
 8	 * @param {string} repo - Repository name (e.g. "ai-insights").
 9	 * @param {string} slug - Project slug (e.g. "2026-05-31-my-plan").
10	 * @returns {string} Composite key in the form `repo/slug`.
11	 */
12	function makeProjectCacheKey(repo, slug) {
13	  return repo + '/' + slug;
14	}
15	
16	function escapeHtml(str) {
17	  if (str === null || str === undefined) return '';
18	  return String(str)
19	    .replace(/&/g, '&amp;')
20	    .replace(/</g, '&lt;')
21	    .replace(/>/g, '&gt;')
22	    .replace(/"/g, '&quot;');
23	}
24	
25	function formatDate(isoString) {
26	  if (!isoString) return '—';
27	  try {
28	    var d = new Date(isoString);
29	    if (isNaN(d.getTime())) return escapeHtml(isoString);
30	    var pad = function (n) { return String(n).padStart(2, '0'); };
31	    var timeStr = pad(d.getHours()) + ':' + pad(d.getMinutes());
32	
33	    var now = new Date();
34	    // Strip times for day-boundary comparisons
35	    var today    = new Date(now.getFullYear(),    now.getMonth(),    now.getDate());
36	    var itemDay  = new Date(d.getFullYear(),      d.getMonth(),      d.getDate());
37	    var diffDays = Math.round((today - itemDay) / 86400000);
38	
39	    if (diffDays === 0) return 'Today, ' + timeStr;
40	    if (diffDays === 1) return 'Yesterday, ' + timeStr;
41	    var months = ['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
42	    if (diffDays < 7)  return ['Sunday','Monday','Tuesday','Wednesday','Thursday','Friday','Saturday'][d.getDay()] + ', ' + d.getDate() + ' ' + months[d.getMonth()] + ', ' + timeStr;
43	
44	    // Older: show short date like "12 Feb 2026, 16:41"
45	    return d.getDate() + ' ' + months[d.getMonth()] + ' ' + d.getFullYear() + ', ' + timeStr;
46	  } catch (_) {
47	    return escapeHtml(isoString);
48	  }
49	}
50	
51	function statusBadge(status) {
52	  if (!status) return '';
53	  var cls = 'badge badge-' + status.toLowerCase().replace(/_/g, '-');
54	  return '<span class="' + cls + '">' + escapeHtml(status) + '</span>';
55	}
56	
57	// Cache of namespaced key → display name, populated by views that fetch project data.
58	// breadcrumb().project() reads from here automatically.
59	// The cache key is the composite `repo + '/' + slug` to prevent collisions
60	// between same-slug projects in different repositories.
61	// Bounded to MAX_SIZE entries; oldest entries are evicted when the cap is exceeded.
62	var ProjectNameCache = (function () {
63	  var MAX_SIZE = 200;
64	  var _cache = {};
65	  var _keys = []; // insertion-order tracker for eviction (no duplicates)
66	
67	  return {
68	    /**
69	     * Store a display name for a project.
70	     * @param {string} key  - Namespaced key in the form `repo/slug` (use makeProjectCacheKey()).
71	     * @param {string} name - Display name to cache.
72	     */
73	    set: function (key, name) {
74	      if (!key || !name || !name.trim()) return;
75	      var trimmed = name.trim();
76	      // Update the value; only add to order tracker if this is a new key.
77	      // NOTE: This is FIFO eviction, not LRU. Updating an existing key refreshes
78	      // its value but does NOT move it to the back of the eviction queue — the key
79	      // retains its original insertion position. For this cache (display names for
80	      // up to 200 projects, rarely refreshed), FIFO is correct and sufficient.

 81	      if (!Object.prototype.hasOwnProperty.call(_cache, key)) {
 82	        _keys.push(key);
 83	        // Evict oldest entry if cap exceeded.
 84	        if (_keys.length > MAX_SIZE) {
 85	          var oldest = _keys.shift();
 86	          delete _cache[oldest];
 87	        }
 88	      }
 89	      _cache[key] = trimmed;
 90	    },
 91	    /**
 92	     * Retrieve the display name for a project.
 93	     * @param {string} key - Namespaced key in the form `repo/slug`.
 94	     *   Falsy values (null, undefined, empty string) are handled gracefully: a null/undefined
 95	     *   key returns null without throwing; an empty string key falls through to the slug
 96	     *   extraction path and returns an empty string.
 97	     * @returns {string|null} Cached display name, or the slug portion of the key (after the
 98	     *   last '/') if not found — so breadcrumbs show a readable label before project data is
 99	     *   fetched. Returns null for null/undefined input.
100	     */
101	    get: function (key) {
102	      if (_cache[key]) return _cache[key];
103	      // Fall back to the slug portion (after the last '/') so breadcrumbs show
104	      // a readable label even before the project data is fetched.
105	      var lastSlash = key ? key.lastIndexOf('/') : -1;
106	      return lastSlash >= 0 ? key.slice(lastSlash + 1) : key;
107	    },
108	    /**
109	     * Returns the current number of cached entries.
110	     * Intended for testing; not part of the public API.
111	     */
112	    _size: function () {
113	      return _keys.length;
114	    },
115	  };
116	}());
117	
118	function breadcrumb() {
119	  var segments = [];
120	  var api = {
121	    projects: function () {
122	      segments.push({ label: 'Projects', href: '#/' });
123	      return api;
124	    },
125	    project: function (repo, slug) {
126	      segments.push({ label: ProjectNameCache.get(makeProjectCacheKey(repo, slug)), href: '#/projects/' + encodeURIComponent(repo) + '/' + encodeURIComponent(slug) });
127	      return api;
128	    },
129	    leaf: function (label) {
130	      segments.push({ label: label });
131	      return api;
132	    },
133	    leafSpan: function (label, id) {
134	      segments.push({ label: label, id: id });
135	      return api;
136	    },
137	    html: function () {
138	      return '<p class="breadcrumb">' +
139	        segments.map(function (s) {
140	          if (s.href) return '<a href="' + s.href + '">' + escapeHtml(s.label) + '</a>';
141	          if (s.id)   return '<span id="' + escapeHtml(s.id) + '">' + escapeHtml(s.label) + '</span>';
142	          return escapeHtml(s.label);
143	        }).join(' / ') +
144	        '</p>';
145	    }
146	  };
147	  return api;
148	}
149	
150	function showLoading(container) {
151	  container.innerHTML = '<div class="loading">Loading…</div>';
152	}
153	
154	function showError(container, message) {
155	  container.innerHTML = '<div class="error-banner">' + escapeHtml(message) + '</div>';
156	}
157	
158	function formatDuration(ms) {
159	  if (ms == null || isNaN(ms) || ms < 0) return '—';
160	  if (ms < 1000) return '< 1s';
161	  var totalSec = Math.floor(ms / 1000);
162	  var hours = Math.floor(totalSec / 3600);
163	  var minutes = Math.floor((totalSec % 3600) / 60);
164	  var seconds = totalSec % 60;
165	  var parts = [];
166	  if (hours > 0) parts.push(hours + 'h');
167	  if (minutes > 0) parts.push(minutes + 'm');
168	  if (seconds > 0 && hours === 0) parts.push(seconds + 's');
169	  return parts.join(' ') || '< 1s';
170	}

